fn hash(seed: i32) -> i32 {
    let mut h: i32 = seed * 747796405 + 2891336453;
    h = (h >> 16) ^ h;
    if h < 0 { h = 0 - h; }
    h
}

fn tri(v: i32) -> i32 {
    let m: i32 = v % 120;
    if m < 60 { m } else { 120 - m }
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, 1);
        host::display::state_set(2, -30);
        host::display::state_set(3, 3);
        host::display::state_set(4, 0);
        host::display::state_set(5, 0);
        host::display::state_set(6, 0);
    }
    let down: i32 = host::display::pointer_down();
    let tap: bool = down == 1 && host::display::state_get(7) == 0;
    host::display::state_set(7, down);
    if host::display::state_get(6) == 1 {
        host::display::clear(0x101018);
        host::display::draw_string(100, 180, "THE FLOCK ESCAPED", 0xff4040, 3);
        host::display::draw_string(140, 250, "BAGGED", 0x808080, 2);
        host::display::draw_number(290, 244, host::display::state_get(4), 0xffffff, 3);
        host::display::draw_string(130, 320, "TAP TO HUNT AGAIN", 0x808080, 2);
        if tap { host::display::state_set(0, 0); }
    } else {
        let round: i32 = host::display::state_get(1);
        let base: i32 = 80 + hash(round * 5) % (h - 240);
        let by: i32 = base + tri(t * 3) - 30;
        let spd: i32 = 2 + hash(round) % 3;
        let mut bx: i32 = host::display::state_get(2) + spd;
        let mut ammo: i32 = host::display::state_get(3);
        let mut next_bird: i32 = 0;
        if tap && ammo > 0 {
            ammo = ammo - 1;
            let dx: i32 = host::display::pointer_x() - bx;
            let dy: i32 = host::display::pointer_y() - by;
            if dx * dx + dy * dy <= 676 {
                host::audio::tone(440, 80, 1);
                host::display::state_set(4, host::display::state_get(4) + 1);
                next_bird = 1;
            }
        }
        if bx > w + 30 {
            let esc: i32 = host::display::state_get(5) + 1;
            host::display::state_set(5, esc);
            if esc >= 3 { host::display::state_set(6, 1); }
            next_bird = 1;
        }
        if next_bird == 1 {
            host::display::state_set(1, round + 1);
            bx = -30;
            ammo = 3;
        }
        host::display::state_set(2, bx);
        host::display::state_set(3, ammo);
        host::display::clear(0x87ceeb);
        host::display::fill_rect(0, h - 50, w, 50, 0x2d6a2d);
        host::display::fill_rect(bx - 12, by - 8, 24, 16, 0x4a3520);
        if (t / 8) % 2 == 0 {
            host::display::fill_triangle(bx - 4, by - 6, bx + 6, by - 6, bx, by - 20, 0x6a4a30);
        } else {
            host::display::fill_triangle(bx - 4, by + 6, bx + 6, by + 6, bx, by + 18, 0x6a4a30);
        }
        host::display::fill_rect(bx + 12, by - 4, 8, 6, 0xffaa00);
        let cpx: i32 = host::display::pointer_x();
        let cpy: i32 = host::display::pointer_y();
        host::display::draw_line(cpx - 14, cpy, cpx + 14, cpy, 0x202020);
        host::display::draw_line(cpx, cpy - 14, cpx, cpy + 14, 0x202020);
        let mut a: i32 = 0;
        while a < ammo {
            host::display::fill_rect(8 + a * 14, h - 30, 8, 20, 0xcc2222);
            a = a + 1;
        }
        host::display::draw_string(8, 8, "BAGGED", 0x204020, 2);
        host::display::draw_number(130, 8, host::display::state_get(4), 0x103010, 2);
        host::display::draw_string(w - 210, 8, "ESCAPED", 0x502020, 2);
        host::display::draw_number(w - 60, 8, host::display::state_get(5), 0x801010, 2);
    }
    host::display::present();
}
